//! Strata core: vault format, crypto, merge, and sync logic.
//!
//! Everything security-critical lives in this crate. The Kotlin side is UI and
//! thin platform adapters only (see `protector::PlatformProtector`).
//! Bindings are generated by UniFFI; see `uniffi.toml`.
//!
//! `docs/spec.md` is the source of truth for every format and construction here.
//! The internal modules are `pub` so integration tests and fuzz targets can reach
//! them; they are not a stable Rust API. Kotlin sees only the UniFFI exports.

uniffi::setup_scaffolding!();

/// Every heap block is zeroed before it is freed (see `alloc`).
#[global_allocator]
static ALLOCATOR: alloc::ZeroizingAlloc = alloc::ZeroizingAlloc;

mod alloc;
pub mod crypto;
pub mod encoding;
pub mod error;
pub mod ffi;
pub mod format;
pub mod kdbx;
pub mod keys;
pub mod local;
pub mod merge;
pub mod model;
pub mod policy;
pub mod protector;
pub mod sync;

/// Version of the core library, so the UI can confirm the native library loaded.
#[uniffi::export]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}
